async function purchase(action){if(busy)return;shopMessage=action.type==='buy'?'ACQUIRING '+VEHICLES[selectedVehicle].name+'…':'INSTALLING '+UPGRADES[action.choice].name+'…';busy=true;renderMenu();try{await command(action);status('');shopMessage=action.type==='buy'?VEHICLES[selectedVehicle].name+' ACQUIRED / READY TO RACE':UPGRADES[action.choice].name+' INSTALLED / TIER '+g.career.upgrades[selectedVehicle][action.choice];audio.unlock();audio.play('collect');announce(shopMessage);}catch(e){shopMessage=e.message;status(e.message);}finally{busy=false;renderMenu();}}
async function start(){closePlan();if(busy||document.hidden||document.documentElement.dataset.orientationBlocked==='true')return;if(!(g.career.owned&(1<<selectedVehicle))){setView('garage');return;}audio.unlock();busy=true;renderMenu();try{await command({type:'race',mode:selectedMode,vehicle:selectedVehicle,gadget,difficulty});renderer.reset();await resume();}catch(e){status(e.message);}finally{busy=false;if(view!=='race')renderMenu();}}
async function resume(){if(!loaded)return void boot();if(g.over){setView('result');return;}if(document.hidden||document.documentElement.dataset.orientationBlocked==='true')return;audio.unlock();await saveAll();await renderer.prepareRace(g);if(!g.tick){lastRecoveryId=null;blockedMs=0;roadblockCueId=null;roadblockCueStage=-1;}clear();audio.unlock();running=false;countdown=1800;accumulator=0;setView('race');hidden($('#countdown'),false);setText('countdown','3');canvas.focus();}
async function pause(){clear();if(!running&&!countdown)return;running=false;countdown=0;hidden($('#countdown'),true);setView('pause');try{await saveAll();}catch{}}
async function finish(){if(ending)return;running=false;clear();busy=true;ending=true;const wreck=g.finish_reason===2&&!motion.matches;renderer.coastTime=renderer.coastDistance=0;
 hidden(actions,true);hidden(stick,true);hidden(pauseButton,true);status('Saving race rewards…');
 try{await Promise.all([saveAll(),new Promise(resolve=>setTimeout(resolve,motion.matches?0:wreck?1700:1100))]);g=structuredClone(confirmed.game);previous=structuredClone(g);status('');}catch{}finally{ending=false;busy=false;setView(g.over?'result':'pause');}}

async function verify(){try{await saveAll();const result=await api('replay',{});status('Verified · '+result.frames+' signed career frames');}catch(e){status(e.message);}}
async function download(){try{await saveAll();const data=await api('export');const u=URL.createObjectURL(new Blob([JSON.stringify(data)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='nightshift-v'+(g.physics_version||8)+'-career.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}catch(e){status(e.message);}}
