 if(running){if(roadblockCueId!==hazard.id){roadblockCueId=hazard.id;roadblockCueStage=-1;}const stage=hazard.eta<2.5?2:hazard.eta<5?1:0;if(stage>roadblockCueStage){roadblockCueStage=stage;audio.play(stage===2?'hazardUrgent':'hazard');if(stage===0)announce(el.getAttribute('aria-label'));}}
