function effects(before,after){
 for(const cue of audio.feedback(before,after))if(cue.type==='ready'&&!motion.matches)$('#charge').children[cue.tier-1]?.animate([{filter:'brightness(2.1)'},{filter:'brightness(1)'}],{duration:320});
 for(const e of combatFeedback(before,after)){
  const player=e.target===-1;
  if(e.kind==='scrape'){renderer.event({type:'scrape'},after,before);}
  else if(e.kind==='collision'||e.kind==='wreck'||e.kind==='shield-break'){renderer.event({type:e.kind},after,before);if(e.kind!=='shield-break')audio.play('damage',after);if(e.kind==='wreck')toast('WRECKED');}
  else if(e.kind==='hit'||e.kind==='disable'||e.kind==='block'){renderer.event({type:player?'hit':e.kind==='block'?'rival-block':e.kind==='disable'?'disable':'rival-hit',id:player?-1:e.target},after,before);if(player){audio.play('damage',after);toast(e.kind==='disable'?'SYSTEMS DISABLED / RECOVERING':'SYSTEM HIT');}else if(e.kind==='disable'&&e.actor===-1){audio.play('enemy');toast('RIVAL DISABLED');}}
  else if(e.kind==='shot'){renderer.event({type:e.actor===-1?'pulse':'rival-shot',id:e.actor,target:e.target},after,before);if(e.actor===-1)audio.play('pulse');}
  else if(e.kind==='guard'&&e.actor===-1){renderer.event({type:'guard'},after,before);audio.play('guard');}
  else if(e.kind==='counter'){renderer.event({type:'counter'},after,before);audio.play('counter');toast('JAMMED / CHARGE +100');}
  else if(e.kind==='dodge')toast('EVADED / CHARGE +60');
  else if(e.kind==='contract')toast('TARGET SECURED / '+combatHud(after).completed+' OF '+EVENTS[after.mode].rivals);
  else if(e.kind==='recover'&&player)toast('SYSTEMS ONLINE');
 }
 if(after.checkpoint>before.checkpoint){toast('RELAY / EQUIPMENT RESTORED');renderer.event({type:'wave'},after,before);}
 if(after.over&&!before.over&&after.won)audio.play('wave');
}

let goUntil=0,lastCount='',blockedMs=0,lastRecoveryId=null;
function frame(now,delta,ratio,features){controls.poll(now);if(goUntil&&now>goUntil){goUntil=0;hidden($('#countdown'),true);}if(countdown){countdown=Math.max(0,countdown-delta);const cue=String(Math.ceil(countdown/600)||'GO');setText('countdown',cue);if(cue!==lastCount){lastCount=cue;audio.play(cue==='GO'?'start':'count');if(!motion.matches)$('#countdown').animate([{opacity:.1,transform:'scale(1.25)'},{opacity:1,transform:'scale(1)'}],{duration:230});}if(!countdown){running=true;goUntil=now+350;accumulator=saveTime=0;}}
 if(running){const opening=roadblockOpening(g);blockedMs=opening&&opening.z> -8&&Math.abs(g.speed)<180?blockedMs+delta:0;if(blockedMs>1200&&lastRecoveryId!==opening.id){lastRecoveryId=opening.id;toast(coarse.matches?'PULL STRAIGHT DOWN TO REVERSE · FOLLOW THE CHEVRONS':(g.ability_ticks?keyLabel(keyConfig.bindings.drift)+' TO BRAKE · ':'')+keyLabel(keyConfig.bindings.reverse)+' TO REVERSE · FOLLOW THE CHEVRONS');}accumulator+=delta;while(accumulator>=1000/30&&running){if(pending.length>=90){void pause();status('Waiting for your connection…');break;}previous=structuredClone(g);const bits=inputs();pending.push(bits);step(g,bits);controls.observe(previous,g,bits);effects(previous,g);accumulator-=1000/30;if(g.over)void finish();}saveTime+=delta;if(saveTime>800){saveTime=0;void flush().catch(()=>{});}}
 if(noticeTime>0){noticeTime-=delta;if(noticeTime<=0)hidden($('#notice'),true);}renderer.draw(g,previous,accumulator/(1000/30),delta,ratio,{running,ending,countdown,features,reduced:motion.matches,low:readQuality()==='low'||ratio<.9});audio.drive(g,running);hudTime+=delta;if(hudTime>=100){hudTime=0;if(view==='race')hud();}lastTick=g.tick;return{gpuMs:renderer.gpu.ms};}
async function boot(){busy=true;status('Connecting…');globalThis.UTXOPlayLoader?.boot();try{const [state]=await Promise.all([api('state'),renderer.load()]);chooseRules(state);await renderer.prepareRace(state.game);renderer.makeThumbnails();confirmed=state;g=structuredClone(state.game);previous=structuredClone(g);selectedMode=g.mode;selectedVehicle=g.vehicle;gadget=g.gadget;difficulty=g.difficulty;loaded=true;status('');globalThis.UTXOPlayLoader?.session();globalThis.UTXOPlayLoader?.ready();setView(g.over?'result':g.tick?'pause':'career');if(g.physics_version!==10)toast('SAVED EVENT / ORIGINAL RULES. NEW EVENTS USE THE UPDATED ROADBLOCK SYSTEM.');}catch(e){status(e.message);globalThis.UTXOPlayLoader?.fail('game');setView('pause');}finally{busy=false;renderMenu();}}
if(new URLSearchParams(location.search).has('review'))globalThis.__driftReview=()=>({game:structuredClone(g),running,countdown,ending,view,loaded,pending:pending.length,sending:!!sending,confirmedTick:confirmed?.game.tick,stick:{x:stickX,y:stickY,owner:stickOwner,reverse:stickReverse},roadblock:roadblockThreat(g),buffer:{width:canvas.width,height:canvas.height},draw:renderer.renderer.info.render,feedback:renderer.combat.snapshot(),audio:audio.snapshot(),car:{position:renderer.car.position.toArray(),rotation:renderer.car.rotation.toArray()},grounding:renderer.wreckGround,motion:{coastTime:renderer.coastTime,coastDistance:renderer.coastDistance,body:renderer.car.userData.rig?.body.rotation.toArray(),contacts:renderer.car.userData.rig?.contacts,exhaust:renderer.car.userData.rig?.exhaust,reflection:renderer.atmosphere?.strength.value,gpuMs:renderer.gpu.ms},environment:{...renderer.lighting.snapshot(),fleetLoaded:renderer.fleetLoaded,fleetSources:renderer.fleetSources,fleetBounds:renderer.fleetBounds,wheelContacts:renderer.fleetContactY},keyboard:structuredClone(keyConfig),controls:controls.snapshot(),engine:renderer.engineSnapshot(),world:{district:renderer.world.current,routeMode:renderer.routeMode,sky:renderer.world.sky},project:(...a)=>renderer.project(...a),pointer:(...a)=>renderer.pointer(...a)});
const plan=$('#race-plan');
function closePlan(){if(!plan||plan.hidden)return;hidden(plan,true);(planFocus?.isConnected?planFocus:$('#menu-actions button'))?.focus({preventScroll:true});}
function openPlan(){planFocus=document.activeElement;renderPlan();hidden(plan,false);plan.querySelector('button').focus();}
function renderPlan(){const event=EVENTS[selectedMode],d=DISCIPLINES[event.type],setup=recommendedSetup(g.career,selectedMode);plan.innerHTML=`<div class="plan-heading"><div><small>${DISTRICTS[selectedMode].name}</small><h2>RACE STRATEGY</h2></div><div class="plan-close"></div></div><div class="plan-layout"><div class="plan-route">${routeSvg(selectedMode)}<b>${event.name}</b><span>${d.goal}</span></div><div class="plan-copy"><h3>${d.name}</h3><p>${d.loop}</p><ol class="plan-sectors">${routeIntel(selectedMode).map((r,n)=>`<li><b>0${n+1}</b><div><strong>${DISTRICTS[selectedMode].zones[n]}</strong><small>${r.startKm.toFixed(1)}–${r.endKm.toFixed(1)} KM · ${r.character} · ${r.changes} BEND CHANGES</small></div></li>`).join('')}</ol></div></div><div class="plan-loadout"><div><small>YOUR LOADOUT</small><b>${VEHICLES[selectedVehicle].name} / ${GADGETS[gadget].name}</b><span>${GADGETS[gadget].detail}</span></div><div class="plan-weapons"></div></div><div class="plan-footer"><div><small>OWNED BUILD SUGGESTION</small><b>${VEHICLES[setup.vehicle].name} / ${GADGETS[setup.gadget].name}</b><span>Changes the next race setup. No purchase.</span></div><div class="plan-apply"></div></div>`;
 plan.querySelector('.plan-close').append(button('close','Close race strategy',closePlan));for(let n=0;n<3;n++){const b=button(['emp','wave','mine'][n],'Equip '+GADGETS[n].name,()=>{gadget=n;renderMenu();renderPlan();plan.querySelectorAll('.plan-weapons button')[n].focus();});b.setAttribute('aria-pressed',String(gadget===n));plan.querySelector('.plan-weapons').append(b);}plan.querySelector('.plan-apply').append(button('wrench','Apply suggested owned loadout',()=>{selectedVehicle=setup.vehicle;gadget=setup.gadget;renderer.setVehicle(selectedVehicle);renderMenu();renderPlan();plan.querySelector('.plan-apply button').focus();}));}
plan.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();closePlan();}if(e.key==='Tab'){const items=[...plan.querySelectorAll('button')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
const engineerToggle=button('help','Toggle race engineer',()=>{engineerEnabled=!engineerEnabled;write('nightshift:engineer',engineerEnabled?'on':'off');engineerToggle.setAttribute('aria-pressed',String(engineerEnabled));});engineerToggle.setAttribute('aria-pressed',String(engineerEnabled));$('#help-actions').append(engineerToggle);
let graphicsPause=Promise.resolve();addEventListener('nightshift:graphics',e=>{if(e.detail.state==='lost'){clear();graphicsPause=pause();status('Restoring graphics…');}else void(async()=>{await graphicsPause;try{await saveAll();location.reload();}catch{status('Graphics restored. Reconnect to resume.');}})();});
setView('career');void boot();const stopRender=startRenderLoop(frame,{active:()=>running||countdown>0||ending,monitor:()=>running});addEventListener('pagehide',e=>{clear();if(!e.persisted){stopRender();renderer.dispose();void audio.context?.close();}});
